// Keep price drops only. The Actor's "onlyNew" mode returns new listings and price changes since the last run.
const rows = $input.all().map((i) => i.json).filter((p) => p.change === 'price_down');
if (!rows.length) return [];
const lines = rows.slice(0, 15).map((p) => `• ${p.title}: ${p.currency || ''} ${p.price} (was ${p.previousPrice}) at ${p.store}${p.googleShoppingUrl ? ` <${p.googleShoppingUrl}|view>` : ''}`);
return [{ json: { message: `🔻 Price drops on Google Shopping:\n${lines.join('\n')}` } }];
